// Indonesian texts of catalog.mjs: [English text, Indonesian text], in catalog order. The English side must match the
// T() text exactly (the build names any text without a translation and any entry whose English text changed or went
// away). Terms follow the app (src/Filee.App/Assets/i18n/id.json): preset, engine / engine opsional (engines), toolbar
// donut / menu donut, irisan (slice), Folder pantau (watch folders), area drop zone (drop zone), bawaan (built in),
// Pengaturan → Engine → Gunakan salinan saya…, preset names as in the app (Kompres PDF, Gabungkan PDF, Vektorisasi ke
// SVG, Gambar garis ke SVG, Ekstrak bingkai…); Anda, like the app.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `video dan audio, ekstraksi subtitle, dan penyimpanan HEIC`],
  [`older office formats such as DOC, PPT and ODT`, `format Office lama seperti DOC, PPT, dan ODT`],
  [`rare e-book formats and MOBI/AZW3 output`, `format e-book langka dan output MOBI/AZW3`],
  [`EPS and PostScript`, `EPS dan PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc, dan markup lainnya, Word → Markdown, serta Markdown → slide`],

  // Options
  [`quality`, `kualitas`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Kualitas JPG, WEBP, dan AVIF dapat diatur: secara bawaan JPG disimpan pada 90%, dan preset JPG 70% menghasilkan file yang lebih kecil.`],
  [`resize`, `ubah ukuran`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Ubah ukuran saat mengonversi, berdasarkan persentase (misalnya setengah ukuran) atau hingga panjang sisi terpanjang tertentu.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Atur DPI yang ditulis ke dalam gambar, misalnya 300 untuk cetak.`],
  [`grayscale`, `skala abu-abu`],
  [`A grayscale preset makes black-and-white copies.`, `Preset skala abu-abu membuat salinan hitam putih.`],
  [`metadata`, `metadata`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Metadata (EXIF, XMP, profil warna) dipertahankan secara bawaan dan dapat dihapus demi privasi.`],
  [`ICO sizes`, `ukuran ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `Secara bawaan file ICO berisi ukuran 256, 128, 64, 48, 32, dan 16 px; ukurannya dapat diubah di preset.`],
  [`TIFF compression`, `kompresi TIFF`],
  [`TIFF compression can be chosen (LZW by default).`, `Kompresi TIFF dapat dipilih (LZW secara bawaan).`],
  [`white background`, `latar belakang putih`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `JPG tidak mendukung transparansi, sehingga area transparan diisi dengan warna putih.`],
  [`merge into one PDF`, `gabungkan menjadi satu PDF`],
  [`The merge preset combines all dropped files into one PDF.`,
    `Preset penggabungan menyatukan semua file yang dilepas menjadi satu PDF.`],
  [`split pages`, `pisahkan halaman`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `Preset pemisahan menyimpan setiap halaman sebagai PDF tersendiri di dalam subfolder.`],
  [`rotate & flip`, `putar & balik`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `Preset putar dan balik memutar gambar ke kiri, ke kanan, atau 180° dan mencerminkannya, setelah orientasi bawaan foto diterapkan.`],
  [`Trace to SVG`, `Vektorisasi ke SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Dua preset mengubah gambar menjadi bentuk vektor: Vektorisasi ke SVG dengan hingga 64 warna, dan Gambar garis ke SVG dalam warna hitam untuk logo, tanda tangan, dan hasil pindaian. Tidak perlu program lain.`],
  [`remove background`, `hapus latar belakang`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `Preset Hapus latar belakang membuat latar polos menjadi transparan: kertas di balik tanda tangan atau stempel, atau latar sebuah logo.`],
  [`page ranges`, `rentang halaman`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Rentang halaman seperti 1-3,5 membatasi konversi hanya pada halaman yang Anda perlukan.`],
  [`render DPI`, `DPI render`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `Secara bawaan halaman dirender pada 150 DPI; pilih 300 DPI untuk kualitas cetak.`],
  [`one long image`, `satu gambar panjang`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `Preset Gambar panjang menyusun semua halaman menjadi satu gambar memanjang, misalnya untuk mengunggah seluruh dokumen sekaligus.`],
  [`compress PDF`, `kompres PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `Preset Kompres PDF memperkecil PDF tanpa mengubahnya dari PDF: gambar diperkecil ke 72, 150, atau 300 dpi dan foto disimpan ulang sebagai JPEG, sementara teks, font, tautan, bookmark, dan formulir tetap utuh. PDF yang tidak bisa diperkecil lagi dibiarkan seperti semula. Jika Ghostscript terpasang, Filee juga dapat mencobanya dan menyimpan hasil yang lebih kecil.`],
  [`a picture per slide`, `satu gambar per slide`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `PPTX (slide) menempatkan gambar setiap halaman pada slide tersendiri, seukuran halamannya, dengan teks halaman di catatan pembicara. Slide terlihat persis seperti PDF tetapi tidak dapat diedit; konversi ke DOCX untuk teks yang dapat diedit.`],
  [`vector PDF`, `PDF vektor`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `PDF tetap berupa vektor, sehingga tetap tajam pada perbesaran berapa pun dan saat dicetak.`],
  [`editable`, `dapat diedit`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `Hasilnya berisi teks dan paragraf asli yang dapat Anda edit, bukan gambar halaman.`],
  [`attachments as ZIP`, `lampiran sebagai ZIP`],
  [`Attachments can be saved separately as one ZIP.`, `Lampiran dapat disimpan terpisah sebagai satu ZIP.`],
  [`one CSV per sheet`, `satu CSV per sheet`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Workbook dengan beberapa sheet menghasilkan satu CSV untuk setiap sheet.`],
  [`layout kept`, `tata letak dipertahankan`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Mempertahankan ukuran dan margin halaman, header dan footer beserta nomor halaman, tabel, kotak teks, bentuk, dan gambar.`],
  [`no Office needed`, `tanpa Office`],
  [`No Microsoft Office or LibreOffice needed.`, `Tidak memerlukan Microsoft Office maupun LibreOffice.`],
  [`no Hancom Office needed`, `tanpa Hancom Office`],
  [`No Hancom Office and no approval dialog.`, `Tanpa Hancom Office dan tanpa dialog persetujuan.`],
  [`no AutoCAD needed`, `tanpa AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`, `Tidak memerlukan AutoCAD maupun penampil DWG.`],
  [`no re-encoding`, `tanpa encoding ulang`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Jika format baru dapat menampung video dan suara apa adanya (MOV iPhone → MP4), keduanya hanya dikemas ulang: kualitas tidak berkurang, HDR dipertahankan, selesai dalam hitungan detik.`],
  [`720p option`, `opsi 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `Preset MP4 720p memperkecil video besar agar mudah dibagikan.`],
  [`extract audio`, `ekstrak audio`],
  [`Only the sound is saved, without the video track.`, `Hanya suaranya yang disimpan, tanpa trek video.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `Preset MP3 128k menghasilkan file yang lebih kecil, ideal untuk rekaman suara.`],
  [`extract`, `ekstrak`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Sebagai gantinya, preset Ekstrak membongkar arsip ke dalam sebuah folder.`],
  [`pack into one ZIP`, `kemas jadi satu ZIP`],
  [`Any selection of files can be packed into one ZIP.`,
    `File apa pun yang dipilih dapat dikemas menjadi satu ZIP.`],
  [`DRM-free books`, `buku tanpa DRM`],
  [`Works with DRM-free books only.`, `Hanya berfungsi untuk buku tanpa DRM.`],
  [`ALAC in M4A`, `ALAC dalam M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`, `M4A dapat berisi ALAC lossless selain AAC.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `Preset video dapat meng-encode HEVC (H.265) atau AV1 untuk file yang lebih kecil, dengan tetap mempertahankan video 10-bit dan HDR.`],
  [`hardware encoding`, `encoding perangkat keras`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Aktifkan Gunakan akselerasi perangkat keras di preset video untuk meng-encode H.264 dan HEVC pada kartu grafis (NVENC, Quick Sync, AMF, VideoToolbox, atau VA-API): jauh lebih cepat dan lebih hemat daya, dengan ukuran sedikit lebih besar pada kualitas yang sama. Opsi ini nonaktif secara bawaan, dan tanpa kartu grafis yang dapat digunakan, video di-encode seperti biasa.`],
  [`every frame`, `setiap bingkai`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Biasanya sebuah video menghasilkan satu bingkai diam. Preset Ekstrak bingkai, atau Simpan setiap bingkai video di preset PNG atau JPG, menyimpan setiap bingkai (atau setiap bingkai ke-N) sebagai gambar di folder di samping video.`],
  [`extract subtitles`, `ekstrak subtitle`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `Preset Ekstrak subtitle pada donut video menyimpan trek subtitle teks pertama dari sebuah video sebagai SRT.`],
  [`saved as UTF-8`, `disimpan sebagai UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Hasil disimpan sebagai UTF-8. File Korea yang disimpan dalam CP949 (EUC-KR) dikenali dan dibaca dengan benar.`],
  [`tables to CSV / Excel`, `tabel ke CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Data berbentuk tabel (daftar record) juga dapat dikonversi ke dan dari CSV serta Excel.`],
  [`picture preview`, `pratinjau gambar`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG atau JPG menghasilkan gambar model yang berbayang, dilihat dari depan kanan atas.`],
  [`colours and textures`, `warna dan tekstur`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Warna, tekstur, dan material dipertahankan jika format tujuan dapat menampungnya. STL hanya menyimpan bentuknya.`],
  [`HDR tone-mapped`, `HDR dengan tone mapping`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `Tangkapan layar HDR yang disimpan Windows sebagai JPEG XR dipetakan tone-nya ke kecerahan normal alih-alih terpotong.`],
  [`Live Photo video`, `video Live Photo`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `Preset Ekstrak video Live Photo menyimpan video dari Live Photo iPhone (LIVP dari iCloud, atau foto beserta MOV-nya) atau Motion Photo Android sebagai MP4 atau MOV. Sebaliknya, preset Live Photo (iPhone) dan Motion Photo (Android) mengubah potongan singkat sebuah video menjadi foto bergerak; fitur ini masih eksperimental.`],
  [`WGS 84 longitude / latitude`, `bujur / lintang WGS 84`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Hasil selalu dalam bujur dan lintang (WGS 84). Shapefile dalam UTM, Web Mercator, Lambert, atau Albers dikonversi, sehingga terbuka di lokasi yang tepat; mengonversi file ke formatnya sendiri akan memproyeksikannya ulang.`],
  [`save as ZIP`, `simpan sebagai ZIP`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Satu Shapefile terdiri dari lima file (.shp, .shx, .dbf, .prj, dan .cpg). Dengan Simpan hasil sebagai ZIP di preset, atau untuk setiap hasil geospasial di pengaturan, semuanya disatukan dalam satu ZIP.`],
  [`Canon CR2 RAW photo`, `Foto RAW Canon CR2`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 adalah format foto RAW yang digunakan kamera DSLR Canon selama bertahun-tahun (model Canon yang lebih baru menyimpan CR3). Format ini menyimpan data sensor yang belum diolah, sehingga memberi banyak ruang untuk penyuntingan.`],
  [`Nikon NEF RAW photo`, `Foto RAW Nikon NEF`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF adalah format foto RAW milik Nikon, yang digunakan oleh DSLR Nikon dan kamera mirrorless Z. Seperti file RAW lainnya, NEF berisi data sensor yang belum diolah dan ukurannya beberapa kali lebih besar daripada JPG.`],

  // Text that needs shaping
  [`DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX with text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) go to PDF and images through the optional LibreOffice engine`,
    `DOCX, TXT, Markdown, HTML, XLSX, PPTX, dan HWPX berisi teks yang perlu shaping (Arab, Ibrani, aksara India, Thai, dan lainnya) dikonversi ke PDF dan gambar dengan engine opsional LibreOffice`],
  [`Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Teks yang perlu shaping (Arab, Ibrani, aksara India, Thai, dan lainnya) adalah pengecualian: file DOCX, TXT, Markdown, HTML, XLSX, PPTX, dan HWPX berisi teks seperti itu dikonversi ke PDF dan gambar dengan engine opsional LibreOffice. Tanpa LibreOffice, file itu gagal dengan pesan yang menyebut nama aksaranya, bukan menjadi PDF yang rusak.`],

  // Images
  [`Images`, `Gambar`],
  [`images`, `gambar`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Foto dan grafis, termasuk HEIC dan Live Photo iPhone, PSD Photoshop, RAW kamera dari semua merek besar, APNG animasi, DICOM, dan tangkapan layar HDR Windows (JPEG XR). Ubah ukuran, putar, atur kualitas dan DPI, atau hapus metadata saat mengonversi, atau ubah gambar menjadi SVG.`],
  [`JPEG image`, `Gambar JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG adalah format foto yang paling banyak digunakan. Kompresi lossy-nya membuat file tetap kecil, tetapi setiap penyimpanan dengan kualitas lebih rendah membuang sebagian detail, dan formatnya tidak mendukung transparansi.`],
  [`PNG image`, `Gambar PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG adalah format gambar lossless dengan transparansi, ideal untuk tangkapan layar, logo, dan grafis bertepi tajam. Foto yang disimpan sebagai PNG biasanya jauh lebih besar daripada JPG.`],
  [`WebP image`, `Gambar WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP adalah format gambar Google untuk web. Format ini mendukung kompresi lossy dan lossless serta transparansi, dan biasanya lebih kecil daripada JPG atau PNG, tetapi beberapa editor dan formulir unggahan masih belum menerimanya.`],
  [`AVIF image`, `Gambar AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF adalah format gambar modern yang berbasis codec video AV1. Kompresinya lebih baik daripada JPG dan WebP, tetapi dukungan di perangkat lunak dan perangkat lama masih terbatas.`],
  [`HEIC / HEIF image`, `Gambar HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF) adalah format foto bawaan iPhone dan iPad. Ukuran fotonya sering kali sekitar setengah dari JPG, tetapi banyak aplikasi Windows, situs web, dan perangkat lama tidak dapat membukanya.`],
  [`GIF image / animation`, `Gambar / animasi GIF`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF adalah format gambar lama yang terbatas pada 256 warna dan mendukung animasi sederhana. Format ini masih menjadi cara universal untuk berbagi animasi pendek tanpa suara di obrolan, dokumen, dan laporan bug.`],
  [`Windows icon`, `Ikon Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO adalah format ikon Windows. Satu file ICO berisi gambar yang sama dalam beberapa ukuran (misalnya 16, 32, 48, dan 256 piksel), sehingga tampak tajam di mana saja, dari taskbar hingga favicon situs web.`],
  [`Photoshop document`, `Dokumen Photoshop`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD adalah format asli Adobe Photoshop. Format ini menyimpan layer, mask, dan pengaturan penyesuaian, sehingga sangat baik untuk penyuntingan, tetapi tidak dapat dibuka oleh sebagian besar penampil gambar atau situs web.`],
  [`macOS icon`, `Ikon macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS adalah format ikon macOS. Seperti ICO, format ini menggabungkan beberapa ukuran dari satu gambar, hingga 1024×1024 untuk layar Retina, dan digunakan untuk ikon aplikasi di Mac.`],
  [`Camera RAW`, `RAW kamera`],
  [`Windows only`, `hanya Windows`],
  [`the photo of the Live Photo`, `foto dari Live Photo`],
  [`the video of the Live Photo`, `video dari Live Photo`],

  // Vector graphics
  [`Vector graphics`, `Grafik vektor`],
  [`vector graphics`, `grafik vektor`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, metafile Windows, Illustrator, EPS/PostScript, serta gambar dari CorelDRAW, Visio, dan LibreOffice Draw. SVG juga dapat menjadi DXF atau DWG untuk CAD.`],
  [`SVG vector graphic`, `Grafik vektor SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG adalah format grafik vektor berbasis XML. Bentuk dan teks tetap tajam pada ukuran berapa pun, sehingga ideal untuk logo dan ikon di web, tetapi banyak aplikasi dan formulir unggahan hanya menerima gambar piksel.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS adalah format vektor dari dunia cetak dan desain, yang sering digunakan untuk logo dan ilustrasi yang dikirim ke percetakan. Sebagian besar aplikasi modern tidak dapat menampilkannya tanpa interpreter PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`, `file AI yang disimpan dengan konten PDF (bawaan Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `Ubah PDF menjadi gambar, dokumen Word atau HWPX yang dapat diedit, slide PowerPoint, teks, atau arsip komik, serta gabungkan, pisahkan, kompres, atau pilih halamannya.`],
  [`PDF document`, `Dokumen PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF adalah standar untuk berbagi dokumen yang harus tampil sama di mana pun. Font, tata letak, dan gambarnya tetap, dan dapat dibuka di perangkat apa pun. Hal itu pula yang membuat PDF sulit diedit.`],
  [`one page`, `satu halaman`],

  // Documents
  [`Documents`, `Dokumen`],
  [`documents`, `dokumen`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Dokumen Word tanpa Microsoft Office, faktur elektronik OFD Tiongkok, format pengolah kata lama dan langka dengan engine opsional LibreOffice, serta email yang tersimpan (EML dan MSG Outlook).`],
  [`Word document`, `Dokumen Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX adalah format Microsoft Word sejak Word 2007 (Office Open XML). Format ini paling umum untuk dokumen yang dapat diedit seperti laporan, surat, dan formulir.`],
  [`Word 97–2003 document`, `Dokumen Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC adalah format biner Word 97–2003. Arsip lama, formulir resmi, dan sistem lawas masih menghasilkannya, tetapi format ini mulai digantikan oleh DOCX.`],
  [`E-mail message`, `Pesan email`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML adalah satu email yang disimpan sebagai file (format MIME), lengkap dengan header, isi pesan, dan lampirannya. Sebagian besar aplikasi email, termasuk Outlook dan Thunderbird, dapat membukanya.`],
  [`Outlook message`, `Pesan Outlook`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG adalah file yang disimpan Microsoft Outlook saat Anda menyeret email keluar darinya. Hanya Outlook yang dapat membukanya, sehingga sulit dibaca di PC tanpa Outlook atau di ponsel.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `HWP/HWPX Korea`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Dokumen Hancom Hangul Korea tanpa Hancom Office: HWP ↔ HWPX, ke PDF, gambar, Word, teks, Markdown, dan HTML, serta HWPX dari Word, Excel, PowerPoint, Markdown, dan PDF.`],
  [`Hangul document (HWP)`, `Dokumen Hangul (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP adalah format dokumen Hancom Office Hangul (한글), pengolah kata standar di kantor pemerintahan, sekolah, dan banyak perusahaan di Korea. Di luar Korea, hanya sedikit program yang dapat membukanya.`],
  [`Hangul document (HWPX)`, `Dokumen Hangul (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX adalah format terbuka berbasis XML dari Hancom Hangul (OWPML, standar nasional Korea KS X 6101). Lembaga publik Korea sedang beralih ke format ini dari format biner HWP.`],

  // Spreadsheets
  [`Spreadsheets`, `Spreadsheet`],
  [`spreadsheets`, `spreadsheet`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Sheet Excel, OpenDocument, dan CSV/TSV, ke PDF dengan penyesuaian halaman seperti di Excel atau saling dikonversi, tanpa Excel.`],
  [`Excel workbook`, `Workbook Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX adalah format workbook Microsoft Excel sejak Excel 2007. Satu workbook dapat berisi beberapa sheet dengan rumus, format, diagram, dan gambar.`],
  [`Excel 97–2003 workbook`, `Workbook Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS adalah format workbook biner Excel 97–2003. Banyak sistem lama serta ekspor dari bank atau aplikasi akuntansi masih menghasilkannya.`],
  [`Comma-separated values`, `Nilai yang dipisahkan koma`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV adalah teks biasa dengan satu baris tabel per baris teks. Semua spreadsheet, database, dan bahasa pemrograman dapat membacanya, tetapi format ini tidak memiliki format tampilan, rumus, atau beberapa sheet.`],

  // Presentations
  [`Presentations`, `Presentasi`],
  [`presentations`, `presentasi`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint ke PDF, gambar, dan HWPX tanpa PowerPoint; PPT lama, ODP, dan Keynote dengan engine opsional LibreOffice.`],
  [`PowerPoint presentation`, `Presentasi PowerPoint`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX adalah format Microsoft PowerPoint sejak PowerPoint 2007. Format ini berisi slide dengan teks, gambar, bentuk, tabel, catatan, dan animasi.`],
  [`PowerPoint 97–2003 presentation`, `Presentasi PowerPoint 97–2003`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT adalah format biner PowerPoint 97–2003. Slide kuliah lama dan presentasi yang diarsipkan sering kali masih berformat PPT.`],

  // Text & markup
  [`Text & markup`, `Teks & markup`],
  [`text and markup`, `teks dan markup`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Teks biasa, Markdown, HTML, dan halaman web tersimpan (MHTML) ke PDF, Word, HWPX, dan EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter, dan markup lainnya menggunakan engine opsional Pandoc, yang juga mengubah Markdown menjadi slide PowerPoint.`],
  [`Plain text`, `Teks biasa`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT adalah teks biasa tanpa format apa pun, format dokumen yang paling sederhana dan portabel. Satu-satunya yang bisa berbeda adalah encoding karakternya (UTF-8, UTF-16, atau code page lama).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown adalah markup ringan berbasis teks biasa: # untuk judul, * untuk daftar, ** untuk huruf tebal. Markdown populer untuk catatan, file README, dan dokumentasi, serta tetap mudah dibaca meski tanpa dirender.`],
  [`Web page (HTML)`, `Halaman web (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML adalah bahasa halaman web. File .html yang tersimpan dapat dibuka di browser apa pun, tetapi tampilannya bergantung pada browser serta gaya dan gambar yang ditautkan, yang mungkin tidak tersedia saat offline.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `file LOG dan skrip (PY, PAC, BAT, COMMAND) dibaca sebagai teks dan tidak pernah dijalankan`],
  [`the saved page, with its pictures`, `halaman yang tersimpan, beserta gambarnya`],

  // Data
  [`Data`, `Data`],
  [`data files`, `file data`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML, dan XML saling dikonversi, serta tabel ke dan dari CSV dan Excel. Kontak vCard ke dan dari CSV, termasuk dari ponsel lama. Tidak ada yang perlu dipasang.`],
  [`JSON data`, `Data JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON adalah format data web: objek, daftar, teks, dan angka dalam teks biasa. API, aplikasi, dan file pengaturan menggunakannya di mana-mana.`],
  [`YAML data`, `Data YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML menyimpan jenis data yang sama dengan JSON, tetapi ditulis dengan indentasi alih-alih tanda kurung. File konfigurasi Docker, Kubernetes, pipeline CI, dan banyak aplikasi menggunakan YAML.`],
  [`vCard contacts`, `Kontak vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf) adalah file standar untuk kontak. Ponsel, Outlook, Google Kontak, dan iCloud mengekspor buku alamat sebagai vCard, sering kali dengan banyak kontak dalam satu file.`],

  // E-books
  [`E-books & comics`, `E-book & komik`],
  [`e-books and comics`, `e-book dan komik`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook, dan arsip komik (CBZ, CBR, CB7…) ke PDF, EPUB, Word, dan lainnya, serta KEPUB untuk e-reader Kobo. Hanya buku tanpa DRM.`],
  [`EPUB e-book`, `E-book EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB adalah standar terbuka untuk e-book. Teks menyesuaikan diri dengan layar apa pun, dan sebagian besar e-reader serta aplikasi baca mendukungnya; Kindle menerima EPUB melalui Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `E-book Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI adalah format e-book Mobipocket lama yang digunakan Amazon Kindle selama bertahun-tahun. Format ini masih umum di koleksi e-book lama, tetapi Amazon telah beralih ke AZW3/KFX dan EPUB.`],

  // Video
  [`Video`, `Video`],
  [`video`, `video`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Semua format video umum ke MP4 (H.264, HEVC, atau AV1), WebM, MOV, MKV, AVI, GIF, atau APNG, dengan opsi 720p, encoding perangkat keras pada kartu grafis, ekstraksi audio ke MP3 atau M4A, dan setiap bingkai disimpan sebagai gambar. Menggunakan engine opsional FFmpeg.`],
  [`MPEG-4 video`, `Video MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Part 14) adalah format video yang paling kompatibel. Format ini dapat diputar di ponsel, TV, browser, dan semua situs video, biasanya dengan video H.264 atau H.265 dan audio AAC.`],
  [`QuickTime movie`, `Film QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV adalah format video QuickTime milik Apple, yang digunakan oleh iPhone dan Mac. Biasanya berisi video H.264 atau HEVC, tetapi beberapa editor, TV, dan situs web lebih baik menangani MP4.`],
  [`Matroska video`, `Video Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska) adalah container terbuka yang fleksibel dan dapat berisi banyak trek video, audio, dan subtitle. Format ini populer untuk film dan rekaman, tetapi ponsel, TV, dan editor tidak selalu dapat memutarnya.`],
  [`WebM video`, `Video WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM adalah format video terbuka yang dibuat untuk browser (video VP8/VP9 atau AV1 dengan audio Vorbis atau Opus). Rekaman layar dan unduhan sering berformat WebM, tetapi banyak editor dan perangkat mengharapkan MP4.`],
  [`AVI video`, `Video AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI adalah container video Microsoft dari tahun 1990-an. Camcorder, kamera lama, dan arsip masih menyimpan file AVI, yang sering kali berukuran besar dan kurang didukung di ponsel.`],
  [`one still frame or every frame`, `satu bingkai diam atau setiap bingkai`],

  // Audio
  [`Audio`, `Audio`],
  [`audio`, `audio`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Musik, rekaman, dan memo suara ke MP3, M4A, WAV, FLAC, OGG, Opus, AAC, atau WavPack dan TTA lossless. APE, DSD, dan DTS juga dapat dibaca. Menggunakan engine opsional FFmpeg.`],
  [`MP3 audio`, `Audio MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 adalah format audio terkompresi klasik. Hampir semua pemutar, sistem audio mobil, dan ponsel dapat memutarnya, sehingga menjadi pilihan paling aman untuk berbagi musik, podcast, dan rekaman.`],
  [`MPEG-4 audio`, `Audio MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A adalah file audio MPEG-4, biasanya AAC, yang digunakan oleh iTunes, memo suara iPhone, dan banyak perekam. Suaranya tetap bagus dengan ukuran kecil, tetapi beberapa pemutar dan sistem audio mobil hanya menerima MP3.`],
  [`WAV audio`, `Audio WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV adalah audio tanpa kompresi (biasanya PCM) yang digunakan untuk merekam dan menyunting. Suaranya persis seperti sumbernya, tetapi memakan sekitar 10 MB per menit dalam kualitas CD.`],
  [`FLAC lossless audio`, `Audio lossless FLAC`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC adalah audio terkompresi lossless: ukurannya kira-kira setengah dari WAV tanpa kehilangan kualitas sedikit pun, sehingga menjadi format favorit untuk koleksi musik dan unduhan hi-res.`],

  // Subtitles
  [`Subtitles`, `Subtitle`],
  [`subtitles`, `subtitle`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML, dan MicroDVD saling dikonversi tanpa engine apa pun, disimpan sebagai UTF-8; SSA dan SCC juga dapat dibaca. File SMI dan SRT Korea dalam CP949 dibaca dengan benar. Subtitle di dalam video diekstrak dengan FFmpeg.`],
  [`SubRip subtitles`, `Subtitle SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) adalah file subtitle yang paling umum: baris bernomor dengan waktu mulai dan selesai serta teks biasa. Hampir semua pemutar, editor, dan situs video menerimanya.`],
  [`Advanced SubStation Alpha subtitles`, `Subtitle Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha) adalah format subtitle bergaya yang dipakai fansub anime dan Aegisub, dengan font, warna, posisi, dan efek. Banyak perangkat dan situs hanya menerima SRT biasa.`],
  [`WebVTT subtitles`, `Subtitle WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt) adalah format subtitle untuk video HTML5. Pemutar web, YouTube, dan platform kursus online menggunakannya.`],
  [`SAMI subtitles (SMI)`, `Subtitle SAMI (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi) adalah format subtitle Microsoft yang mirip HTML. Format ini masih menjadi file subtitle klasik di Korea, sering disimpan dalam encoding lama CP949 yang ditampilkan sebagai teks rusak oleh pemutar yang lebih baru.`],

  // Archives
  [`Archives`, `Arsip`],
  [`archives`, `arsip`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `Kemas ulang atau ekstrak ZIP, 7Z, RAR, TAR, image disk, dan banyak format arsip lainnya dengan engine 7-Zip yang disertakan, atau kemas file apa pun menjadi satu ZIP.`],
  [`ZIP archive`, `Arsip ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP adalah format arsip universal. Windows, macOS, ponsel, dan hampir semua formulir unggahan dapat membukanya tanpa perangkat lunak tambahan.`],
  [`7-Zip archive`, `Arsip 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z adalah format arsip terbuka dari 7-Zip. Kompresi LZMA2-nya biasanya menghasilkan file yang lebih kecil daripada ZIP, tetapi tidak semua sistem atau situs web dapat membukanya.`],
  [`RAR archive`, `Arsip RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR adalah format arsip berpemilik dari WinRAR, yang umum untuk unduhan yang dipecah menjadi beberapa bagian. Versi Windows 11 terbaru dapat membuka RAR tetapi tidak dapat membuatnya, dan banyak alat hanya menerima ZIP.`],
  [`Any files`, `File apa pun`],

  // CAD
  [`CAD drawings`, `Gambar CAD`],
  [`CAD drawings [in running text]`, `gambar CAD`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `DWG dan DXF AutoCAD: konversi satu sama lain atau ke PDF, SVG, dan PNG, tanpa AutoCAD.`],
  [`AutoCAD drawing`, `Gambar AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG adalah format gambar asli AutoCAD dan file CAD yang paling umum di bidang arsitektur dan teknik. Tanpa AutoCAD atau penampil DWG, file ini sulit dibuka atau dibagikan.`],
  [`Drawing Exchange Format`, `Drawing Exchange Format`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format) adalah format pertukaran Autodesk untuk gambar CAD. Mesin pemotong laser, perangkat lunak CNC, dan sebagian besar program CAD dapat membacanya, sehingga format ini menjadi cara umum untuk memindahkan gambar antaralat.`],

  // 3D
  [`3D models`, `Model 3D`],
  [`3D models [in running text]`, `model 3D`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF, dan PLY saling dikonversi, dan FBX ke salah satunya, dengan warna, tekstur, dan material jika formatnya mendukung, serta ke gambar PNG atau JPG berbayang. Tidak ada yang perlu dipasang.`],
  [`glTF binary (GLB)`, `glTF biner (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB adalah versi satu file dari glTF, format 3D untuk web, AR, dan game engine. Mesh, material, dan tekstur dikemas dalam satu file yang ringkas.`],
  [`STL 3D model`, `Model 3D STL`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL adalah file klasik untuk pencetakan 3D. File ini hanya menyimpan segitiga sebuah bentuk, tanpa warna atau satuan, dan semua slicer serta program CAD dapat membacanya.`],
  [`Wavefront OBJ model`, `Model Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront) adalah format 3D berbasis teks biasa yang dapat dibuka hampir semua program 3D. Material dan teksturnya berada di sampingnya dalam file .mtl dan file gambar.`],

  // Fonts
  [`Fonts`, `Font`],
  [`fonts`, `font`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Font desktop dan web: TTF, OTF, WOFF, WOFF2, dan EOT saling dikonversi.`],
  [`TrueType font`, `Font TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType) adalah format font desktop yang paling umum di Windows dan macOS. Pasang font ini untuk menggunakannya di aplikasi apa pun.`],
  [`OpenType font`, `Font OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType) adalah format font buatan Adobe dan Microsoft. Font OpenType dengan outline PostScript (CFF) umum dipakai untuk typeface profesional dan mendukung fitur seperti ligatur.`],
  [`Web font (WOFF2)`, `Font web (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 adalah format font web terkompresi yang didukung semua browser modern. Ukurannya biasanya sekitar 30% lebih kecil daripada WOFF, sehingga halaman dimuat lebih cepat.`],

  // Geospatial
  [`Geospatial data`, `Data geospasial`],
  [`geospatial data`, `data geospasial`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Data peta dan GPS: GeoJSON, KML, KMZ, GPX, dan Shapefile saling dikonversi serta ke CSV, Excel, dan JSON, dan CSV berkoordinat kembali menjadi file peta. Hanya data vektor (titik, garis, dan area), selalu disimpan dalam bujur dan lintang. Tidak ada yang perlu dipasang.`],
  [`one row per feature, with its coordinates`, `satu baris per fitur, beserta koordinatnya`],
  [`a CSV with longitude and latitude columns or WKT`, `CSV dengan kolom bujur dan lintang atau WKT`],

  // Camera RAW
  [`Camera RAW photo`, `Foto RAW kamera`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `File RAW kamera (CR2, CR3, NEF, ARW, DNG, RAF, ORF, dan lainnya) berisi data sensor foto yang belum diolah. File ini menyimpan detail paling banyak untuk penyuntingan, tetapi berukuran besar dan memerlukan perangkat lunak khusus untuk melihatnya.`],

  // Conversion guides
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `JPG adalah pilihan aman saat situs web, aplikasi Windows lama, atau seseorang tanpa iPhone membutuhkan foto Anda. Sekumpulan foto HEIC dikonversi sekaligus, dan setiap JPG disimpan di samping file aslinya.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Pilih PNG jika Anda ingin terus menyunting foto tanpa menambah satu putaran kompresi JPG. PNG bersifat lossless, jadi ukuran filenya bisa beberapa kali lebih besar daripada HEIC aslinya.`],

  // Conversion guides
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `HEIC menyimpan foto dalam sekitar setengah ruang JPG dengan kualitas yang sama, seperti cara iPhone menyimpan foto. Menyimpan HEIC memerlukan engine gratis FFmpeg (sekitar 100 MB, diunduh sekali di aplikasi). EXIF, profil warna, dan orientasi dipertahankan.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Gambar yang disimpan dari situs web sering berformat WebP. Mengonversinya ke PNG mempertahankan kualitas penuh dan transparansi yang ada, sehingga hasilnya dapat digunakan di semua editor, presentasi, dan dokumen.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Pilih JPG jika gambarnya berupa foto dan ukuran file penting, misalnya untuk formulir unggahan yang menolak WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `Tangkapan layar dan foto ekspor yang disimpan sebagai PNG bisa berukuran banyak megabyte. Foto biasanya menjadi jauh lebih kecil sebagai JPG; untuk tangkapan layar yang banyak teks dan logo, PNG sering kali tetap menjadi format yang lebih baik.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Mengonversi JPG ke PNG tidak mengembalikan detail yang hilang akibat kompresi JPG, tetapi mencegah kehilangan lebih lanjut: setiap penyuntingan dan penyimpanan berikutnya tetap lossless. Konversikan sebelum Anda me-retouch gambar atau menambahkan transparansi di editor.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Gambar AVIF dari situs web dan ponsel modern tidak dapat dibuka di banyak program lama, penampil gambar, dan formulir unggahan. JPG dapat dibuka di mana saja, dengan konsekuensi ukuran file yang sedikit lebih besar.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `WebP ideal untuk situs web: foto menjadi jauh lebih kecil daripada JPG dan grafis tetap mempertahankan transparansinya. Preset WEBP menyimpan dengan kualitas 85, keseimbangan yang baik untuk web.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Halaman hasil pindaian, struk, dan foto dokumen sering kali harus dikirim sebagai satu PDF. Lepaskan gambar di preset penggabungan untuk mendapatkan satu PDF, atau di PDF untuk mendapatkan satu PDF per gambar. Secara bawaan setiap halaman mengikuti ukuran gambarnya.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Satu ICO mencakup semua yang dibutuhkan Windows untuk ikon desktop, Explorer, dan taskbar, dan juga dapat digunakan sebagai favicon situs web. Mulailah dari PNG persegi berukuran minimal 256×256 px untuk hasil paling tajam.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Membuat ikon aplikasi Mac di Windows biasanya memerlukan alat tambahan; Filee langsung mengubah PNG menjadi file ICNS. Gunakan PNG persegi 1024×1024 px agar ukuran Retina tetap tajam.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Bagikan desain Photoshop kepada orang yang tidak memiliki Photoshop: PNG menampilkan gambar seperti saat disimpan, dengan layer yang terlihat digabungkan dan transparansi dipertahankan. PNG tidak dapat menyimpan layer, jadi simpan PSD-nya untuk penyuntingan.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee membaca file RAW dari Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One, dan lainnya, lalu memprosesnya dengan pengaturan bawaan. Ini cara cepat untuk mendapatkan JPG yang siap dibagikan dari sesi pemotretan; untuk penyuntingan kreatif, gunakan editor RAW terlebih dahulu.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Lepaskan file CR2 dari satu kartu memori penuh sekaligus: Filee mengonversinya secara paralel dan menyimpan setiap JPG di samping file RAW-nya. Kamera Canon yang lebih baru menyimpan CR3, yang juga dapat dibaca Filee.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `File NEF terlalu besar dan terlalu tidak umum untuk dikirim apa adanya. Sebagai JPG, file ini menjadi foto kecil yang dapat dilihat di mana saja; gunakan preset JPG 70% atau Setengah ukuran untuk aplikasi perpesanan. File NRW Nikon dari kamera Coolpix juga dapat dikonversi dengan cara yang sama.`],
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Banyak aplikasi, presentasi, dan formulir unggahan tidak menerima SVG. Filee merender gambar vektor menjadi PNG dengan transparansi; file SVGZ terkompresi juga didukung.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `SVG ke PDF tetap berupa vektor: garis dan teks tetap tajam pada perbesaran berapa pun dan saat dicetak, dan ukuran filenya tetap kecil. Praktis untuk mengirim logo dan diagram ke percetakan atau memasukkannya ke dokumen.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS hanya dapat ditampilkan oleh interpreter PostScript; Filee menggunakan Ghostscript untuk itu. PDF mempertahankan karya vektornya, sehingga dapat dibuka di mana saja dan tetap tajam saat dicetak. File PostScript (.ps) juga dikonversi dengan cara yang sama.`],
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Setiap halaman menjadi JPG tersendiri, sehingga PDF 10 halaman menghasilkan 10 gambar. Praktis untuk obrolan, slide, dan unggahan media sosial yang menerima gambar tetapi tidak menerima PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `PNG menjaga teks dan garis tetap tajam tanpa artefak JPG, cocok untuk slide, diagram, partitur musik, dan halaman yang ingin Anda beri anotasi atau masukkan ke presentasi.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee mengubah PDF menjadi dokumen Word dengan paragraf asli, bukan gambar halaman, sehingga Anda dapat memperbaiki salah ketik atau memakai ulang teksnya. Tata letak yang rumit mungkin perlu dirapikan, dan PDF hasil pindaian yang hanya berisi gambar halaman tidak memiliki teks untuk diekstrak.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee otomatis menempuh jalur PDF → Word → EPUB, sehingga teks menyesuaikan diri dengan layar ponsel atau e-reader. Hasil terbaik didapat dari PDF yang berisi teks asli. Judul menjadi paragraf biasa, dan halaman hasil pindaian tidak memiliki teks untuk dikonversi.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee memindahkan teks PDF ke dokumen Word, menulisnya sebagai HWPX, lalu menyimpannya sebagai HWP, semuanya dengan engine bawaan. Cara ini berfungsi untuk PDF yang berisi teks asli. Tata letak yang rumit mungkin perlu dirapikan, dan halaman hasil pindaian tidak memiliki teks untuk diambil.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee mengubah PDF menjadi dokumen Word terlebih dahulu, lalu menjadi Markdown, dengan mempertahankan paragraf, judul, dan teks tebal jika dapat membedakannya. Berguna untuk catatan, wiki, atau menempelkan teks ke alat lain. Halaman hasil pindaian tidak memiliki teks untuk dikonversi.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Kantor-kantor di Korea sering membutuhkan dokumen dalam format Hangul. Filee mengonversi teks PDF menjadi file HWPX yang dapat Anda buka dan edit di Hancom Hangul, tanpa Hancom Office untuk konversinya; ubah menjadi HWP setelahnya jika formulir mengharuskan format lama.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Praktis saat PDF harus ditampilkan di PowerPoint atau ditambahkan ke presentasi yang sudah ada: setiap halaman menjadi slide yang tampak persis seperti PDF, dan teks halamannya tersedia di catatan pembicara. Slide berupa gambar, jadi untuk mengubah isi teksnya, konversikan PDF ke DOCX saja.`],
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Tidak perlu Microsoft Word atau LibreOffice: Filee membaca DOCX sendiri dan menata halamannya lengkap dengan header, footer, tabel, dan gambar. Lepaskan beberapa dokumen di preset penggabungan untuk menyatukannya menjadi satu PDF.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Dokumen Word 97–2003 lama dari arsip, formulir resmi, atau sistem lawas menjadi PDF yang dapat dibuka di mana saja. Engine yang sama juga mengonversi file ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord, dan Apple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Simpan email sebagai PDF untuk arsip, faktur, atau berkas hukum: PDF menampilkan pengirim, penerima, tanggal, subjek, dan isi pesan, serta dapat dibuka di mana saja tanpa aplikasi email.`],
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee merender halaman HWP dengan rhwp, engine Hangul open source, sehingga Hancom Office maupun dialog persetujuannya tidak terlibat. Berguna untuk mengirim dokumen Korea kepada orang yang tidak dapat membuka HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Ubah dokumen Hangul menjadi file Word yang dapat diedit rekan kerja di luar negeri. Teks, paragraf, dan tabel ikut dipindahkan; tata letak dengan banyak objek mengambang sebaiknya diperiksa sekilas di Word.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `HWPX, format Hangul yang lebih baru berbasis XML, dikonversi seperti HWP: engine bawaan rhwp menata halamannya, sepenuhnya offline. Praktis untuk mengarsipkan formulir HWPX dari lembaga publik sebagai PDF.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Beberapa sistem dan alur kerja yang lebih baru hanya menerima HWPX. Filee mengonversi HWP biner ke HWPX dengan rhwp, tanpa Hancom Office, dan mengonversi sekumpulan dokumen lama sekaligus.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Versi Hangul yang lebih lama dan beberapa portal pengajuan masih mengharuskan .hwp. Filee mengonversi HWPX kembali ke HWP dengan rhwp, sehingga Anda tidak perlu membuka dan menyimpan ulang setiap file di Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `Penulis HWPX milik Filee sendiri membawa tata letak Word: ukuran dan margin halaman, header dan footer beserta nomor halaman, tabel dengan sel gabungan, garis tepi dan arsiran, kotak teks, bentuk, dan gambar. Setiap file yang ditulisnya diperiksa dengan tiga pembaca HWPX independen dalam pengujian.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Untuk kantor dan formulir yang masih meminta .hwp. Filee menulis dokumen Word sebagai HWPX dengan penulisnya sendiri lalu mengonversinya ke HWP dengan rhwp, keduanya bawaan, sehingga Hancom Office tidak diperlukan untuk konversinya.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Setiap halaman dokumen Word menjadi JPG (Filee menata dokumen sebagai PDF terlebih dahulu), praktis untuk mengunggah satu halaman secara online atau mengirim pratinjau singkat. Tidak perlu Word.`],
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Setiap sheet yang terlihat menjadi bagian tersendiri, dengan format angka, font, isian warna, garis tepi, dan sel gabungan seperti yang ditampilkan Excel. Sheet yang lebar diskalakan ke lebar halaman seperti "Paskan Semua Kolom pada Satu Halaman" di Excel, dan baris header yang dibekukan diulang di setiap halaman.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `CSV hanya berisi satu tabel, sehingga Filee menulis satu CSV untuk setiap sheet. Sel diekspor sebagai nilai, siap untuk database, skrip, dan formulir impor.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Workbook XLSX dapat menyimpan format, rumus, dan sheet tambahan yang tidak dapat disimpan CSV. Pilih semua hasil ekspor CSV Anda dan lepaskan sekaligus untuk mendapatkan satu workbook per file, tanpa dialog impor Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Perbarui workbook Excel 97–2003 lama tanpa Excel atau LibreOffice: konversinya sudah bawaan. File XLSX biasanya lebih kecil, tidak dapat membawa makro, dan dapat dibuka di semua aplikasi spreadsheet saat ini.`],
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Setiap slide menjadi satu halaman PDF seukuran slide-nya, dengan teks, bentuk, gambar, tabel, dan desain master. Praktis untuk membagikan presentasi atau mengunggahnya ke tempat yang tidak menerima file PowerPoint. Animasi dan catatan pembicara tidak termasuk dalam PDF.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Presentasi PowerPoint 97–2003 lama menjadi PDF yang dapat dibuka, dicetak, atau diunggah siapa saja. Presentasi Keynote (.key), ODP, dan WPS (DPS) dikonversi dengan cara yang sama.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Setiap slide menjadi JPG, siap untuk unggahan media sosial, thumbnail, pesan obrolan, atau editor video. Pilih PNG jika slide berisi banyak teks kecil.`],
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Judul, daftar (termasuk daftar tugas), tabel, kode, kutipan, tautan, gambar, catatan kaki, dan rumus matematika ditata pada halaman A4, tanpa Pandoc, LaTeX, atau browser. Cara cepat untuk berbagi catatan dan file README dengan orang yang tidak membaca Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Bawaan, tidak perlu Pandoc. Judul, daftar, tabel, tautan, dan catatan kaki ikut terbawa, sehingga Anda dapat terus menyunting dan mengubah gaya dokumen di Word.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Teks biasa menjadi PDF A4 yang rapi dengan satu paragraf per baris. Filee mengenali file teks UTF-8 dan UTF-16 serta file teks Korea lama (CP949), sehingga log dan catatan lama tidak berubah menjadi karakter acak.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Simpan halaman web atau laporan HTML sebagai PDF yang tampil sama di mana saja dan dapat diarsipkan atau dicetak. Filee mengonversi file .html yang tersimpan di PC Anda, dan beberapa file dapat digabungkan menjadi satu PDF.`],
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `PDF mempertahankan tata letak halaman yang tetap, sehingga praktis untuk mencetak e-book, membacanya di PC, atau mengirimnya ke perangkat tanpa pembaca EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Pindahkan koleksi Kindle/Mobipocket lama ke EPUB agar dapat dibuka di Apple Books, Google Play Buku, Kobo, dan sebagian besar aplikasi baca. Arah konversi ini sudah bawaan, jadi Calibre tidak diperlukan.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `File MOBI dan AZW3 ditulis oleh Calibre, alat untuk e-book. Kindle saat ini juga menerima EPUB melalui Send to Kindle, jadi MOBI terutama berguna untuk perangkat dan aplikasi Kindle lama.`],
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Simpan suara dari kuliah, konser, atau wawancara sebagai MP3 yang dapat diputar di mana saja: di mobil, di pemutar lama, atau di alat transkripsi.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `Video iPhone dan Mac berupa file MOV. Sebagai MP4, video tersebut dapat diputar di ponsel Android, smart TV, aplikasi Windows lama, dan formulir unggahan yang menolak MOV. Video dan suaranya biasanya dapat masuk ke MP4 apa adanya, sehingga Filee hanya mengemasnya ulang: kualitas tidak berkurang, HDR dipertahankan, selesai dalam hitungan detik. Preset MP4 720p memperkecil klip 4K agar mudah dibagikan.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Rekaman MKV, misalnya dari OBS, sering kali tidak dapat diimpor ke editor video atau diputar di TV, sementara MP4 diterima hampir di mana saja. Konversi berjalan secara lokal, sehingga rekaman panjang tidak perlu diunggah.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Rekaman layar dan video yang disimpan dari browser sering berformat WebM, yang kurang baik ditangani oleh banyak editor video, pemutar lama, dan aplikasi perpesanan. MP4 dapat diputar hampir di mana saja, dan sekumpulan klip dapat dikonversi sekaligus.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Ubah klip pendek menjadi GIF animasi untuk obrolan, dokumentasi, atau laporan bug. Buat tetap pendek: GIF menyimpan setiap bingkai sebagai gambar 256 warna, sehingga video yang panjang atau beresolusi tinggi menghasilkan file yang sangat besar.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Video yang dilepas di JPG menghasilkan satu gambar diam. Untuk memilih thumbnail atau menelusuri klip bingkai demi bingkai, gunakan preset Ekstrak bingkai (JPG): gambar-gambarnya disimpan di folder di samping video, setiap bingkai atau setiap bingkai ke-N. Video yang akan menghasilkan lebih dari 100.000 gambar atau memenuhi disk ditolak sebelum dimulai.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `File AVI dari camcorder dan kamera lama berukuran besar dan sering menggunakan codec yang tidak lagi dapat diputar oleh ponsel dan TV. MP4 dengan kompresi modern biasanya jauh lebih kecil dan dapat diputar di mana saja.`],
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Rekaman WAV memakan sekitar 10 MB per menit; sebagai MP3, ukurannya hanya sebagian kecil dari itu dan tetap dapat diputar di semua perangkat.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Simpan koleksi FLAC lossless Anda di rumah dan taruh salinan MP3 di ponsel, flashdisk untuk mobil, atau pemutar lama yang tidak dapat memutar FLAC. Seluruh album dapat dikonversi sekaligus.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `Memo suara iPhone, unduhan iTunes tanpa DRM, dan banyak perekam menghasilkan M4A. MP3 diterima oleh semua pemutar, sistem audio mobil, dan formulir unggahan.`],
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Kemas ulang arsip RAR sebagai ZIP untuk orang, formulir unggahan, dan sistem yang hanya menerima ZIP. WinRAR tidak diperlukan, baik untuk membaca RAR maupun untuk menulis ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `7Z sering kali memampatkan lebih baik, tetapi ZIP dapat dibuka di komputer atau ponsel apa pun tanpa perangkat lunak tambahan. Konversikan saat Anda mengirim arsip kepada seseorang yang tidak memiliki 7-Zip.`],
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Kirim gambar kerja kepada klien, tim lapangan, atau percetakan yang tidak memiliki AutoCAD: PDF dapat dibuka di PC atau ponsel apa pun. Beberapa gambar dapat digabungkan menjadi satu PDF.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `File DXF dari program CAD, pekerjaan pemotongan laser, atau pertukaran desain menjadi PDF yang dapat dibuka dan dicetak siapa saja. SVG dan PNG juga tersedia, misalnya untuk pratinjau web.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF adalah format pertukaran yang dapat dibaca mesin pemotong laser, perangkat lunak CNC, dan sebagian besar program CAD. Mengonversi DWG ke DXF memungkinkan Anda membuka gambar AutoCAD di alat-alat tersebut, dan DXF kembali ke DWG juga bisa.`],
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Hosting sendiri font di situs web Anda: WOFF2 adalah format font web terkompresi yang didukung semua browser modern, biasanya sekitar 30% lebih kecil daripada WOFF. Pastikan lisensi font mengizinkan penyematan di web.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Beberapa program lama, mesin pemotong dan bordir, serta game engine hanya menerima font TrueType. Konversikan seluruh keluarga font OTF ke TTF sekaligus, tanpa editor font.`],
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Gunakan Gambar garis ke SVG untuk logo, tanda tangan, dan hasil pindaian: tintanya menjadi satu bentuk hitam di atas latar transparan. Vektorisasi ke SVG mempertahankan hingga 64 warna untuk ikon dan ilustrasi. Foto akan menjadi bidang-bidang warna datar, jadi vektorisasi paling cocok untuk gambar ilustrasi.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `JPG berisi logo atau sketsa hasil pindaian menjadi SVG yang tetap tajam pada ukuran berapa pun, siap untuk plotter pemotong, situs web, atau percetakan. Noise JPG berubah menjadi bintik-bintik, jadi turunkan pengaturan Tingkat detail di preset jika hasilnya tampak ramai.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Mesin pemotong laser, perangkat lunak CNC, dan program CAD membaca DXF. Filee menulis outline SVG dalam milimeter, sehingga bentuk selebar 100 mm tetap 100 mm. Kurva menjadi polyline halus. Isian, gambar, dan filter tidak disertakan.`],
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Email yang diseret keluar dari Outlook berupa file MSG yang hanya dapat dibuka Outlook. Sebagai PDF, email tetap memuat pengirim, penerima, tanggal, subjek, dan isi pesan, serta dapat dibuka di mana saja. Tidak perlu Outlook.`],
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML lebih mudah dibaca dan diedit secara manual, itulah sebabnya file konfigurasi menggunakannya. Urutan key dipertahankan, dan teks yang bisa terbaca sebagai angka atau true/false diberi tanda kutip.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Ubah file konfigurasi menjadi JSON untuk API, skrip, atau alat yang hanya membaca JSON. Anchor dan alias diuraikan, dan file berisi beberapa dokumen menjadi satu array. Komentar dihapus, karena JSON tidak mendukungnya.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Daftar record JSON menjadi tabel yang dapat Anda buka di Excel: satu baris per record, satu kolom per key. Pembungkus seperti {"users": […]} ditelusuri isinya. Data yang bukan tabel dihentikan dengan pesan alih-alih menghasilkan file rusak.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Masukkan buku alamat ke Excel atau alat pengiriman email: satu baris per kontak dengan nama, organisasi, email, telepon, alamat, dan tanggal lahir. Kontak dari ponsel Korea lama dalam CP949 dibaca dengan benar.`],
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Pemutar web dan platform kursus online membutuhkan WebVTT. Waktu tampil, pemisah baris, dan huruf miring ikut terbawa, dan tidak perlu engine apa pun.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Banyak pemutar, TV, dan editor tidak membaca SMI, dan file SMI Korea lama sering tampil sebagai teks rusak. Filee mendeteksi CP949, memilih bahasa dengan baris terbanyak, dan menyimpan SRT UTF-8 yang bersih.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Saat TV, ponsel, atau situs video menolak subtitle ASS bergaya, SRT biasa dapat digunakan. Huruf tebal, miring, garis bawah, dan warna dipertahankan; posisi, font, dan efek dihapus.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Keluarkan subtitle dari film untuk menyunting atau menerjemahkannya. Trek subtitle teks pertama disimpan sebagai SRT; subtitle berbasis gambar (DVD, Blu-ray) tidak dapat diubah menjadi teks. Memerlukan engine gratis FFmpeg.`],
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Buka file cetak di program 3D yang lebih menyukai OBJ. STL tidak memiliki satuan, sehingga Filee membacanya sebagai milimeter dan menulis OBJ dalam milimeter juga, dengan sumbu Y mengarah ke atas seperti kebanyakan program 3D.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Slicer untuk printer 3D menerima STL. Bidang dengan bentuk apa pun dipecah menjadi segitiga, dan Y-atas menjadi Z-atas, sehingga model yang tegak berdiri di atas bed cetak. STL hanya menyimpan bentuk, jadi warna dan tekstur tetap berada di OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Bawa model dari web atau game engine ke program yang membaca OBJ. File .mtl dan teksturnya ditulis di samping file .obj, jadi simpan semuanya bersama-sama.`],

  // FAQ
  [`Is Filee really free?`, `Apakah Filee benar-benar gratis?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Ya. Filee gratis dan open source di bawah lisensi MIT: tanpa iklan, tanpa watermark, tanpa akun, tanpa masa uji coba, dan tanpa batasan jumlah atau ukuran file dari Filee sendiri.`],
  [`Does it work offline? Are my files uploaded?`, `Apakah bisa bekerja offline? Apakah file saya diunggah?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Setiap konversi berjalan di PC Anda sendiri dan file tidak pernah diunggah. Internet hanya digunakan untuk mengunduh engine opsional atau memeriksa pembaruan, sehingga dokumen rahasia, foto, dan rekaman tetap berada di komputer Anda.`],
  [`Which file formats does Filee support?`, `Format file apa saja yang didukung Filee?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee membaca {formatTotal} format file dalam {categoryCount} kategori: {categoryList}. {builtinTotal} di antaranya langsung berfungsi setelah instalasi; sisanya menggunakan engine opsional gratis. Katalog format mencantumkan setiap format dan format tujuan konversinya.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Apakah saya memerlukan Microsoft Office, Hancom Office, atau LibreOffice?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF. Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Tidak. File Word, Excel, dan PowerPoint (DOCX, XLSX, XLS, CSV, PPTX) serta dokumen HWP/HWPX Korea dikonversi oleh engine bawaan Filee. Filee tidak menggunakan Office maupun Hancom Office meskipun keduanya terpasang; LibreOffice hanya unduhan opsional di dalam aplikasi untuk format lama seperti DOC, PPT, ODT, dan RTF. Teks yang perlu shaping (Arab, Ibrani, aksara India, Thai, dan lainnya) adalah pengecualian: file DOCX, TXT, Markdown, HTML, XLSX, PPTX, dan HWPX berisi teks seperti itu dikonversi ke PDF dan gambar dengan engine opsional LibreOffice. Tanpa LibreOffice, file itu gagal dengan pesan yang menyebut nama aksaranya, bukan menjadi PDF yang rusak.`],
  [`What are the optional engines?`, `Apa itu engine opsional?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Engine berukuran besar tidak disertakan dalam installer. Centang engine tersebut di halaman engine pada installer, atau unduh di dalam Filee kapan pun Anda membutuhkannya: {engineDetails}. Engine disimpan di folder milik Filee sendiri dan dapat dihapus kapan saja, dan aplikasi menampilkan versinya, kecepatan unduhan, serta sisa waktunya. Jika FFmpeg, calibre, Pandoc, Ghostscript, atau LibreOffice sudah ada di PC Anda (di PATH, termasuk Scoop, atau di Program Files), Filee menggunakannya dan melewati unduhan, serta memberi tahu jika salinan itu lebih lama daripada versi yang diuji bersama Filee. Pengaturan → Engine → Gunakan salinan saya… memilih salinan tertentu.`],
  [`Does installing Filee need administrator rights?`, `Apakah instalasi Filee memerlukan hak administrator?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Hanya sekali, saat instalasi. Installer memasang Filee di Program Files untuk semua pengguna dan, di Windows 11, menambahkan “Konversi dengan Filee” di bagian atas menu File Explorer. Setelah itu Filee berjalan sebagai pengguna biasa Anda. Untuk instalasi senyap, jalankan installer dengan /VERYSILENT /SUPPRESSMSGBOXES. Jika Anda tidak dapat memasang program, gunakan ZIP portabel: ekstrak di mana saja lalu jalankan Filee.exe.`],
  [`Filee doesn't start on Windows 10: no window, no error. What can I do?`,
    `Filee tidak mau berjalan di Windows 10: tanpa jendela, tanpa pesan error. Apa yang bisa saya lakukan?`],
  [`This happens on a Windows 10 that hasn't been updated for a long time, on a PC whose processor supports Hardware-enforced Stack Protection (CET). Windows turns that protection on but lacks a part that .NET needs, so Filee and its installer stop right away, without a window or a message. Installing the available Windows updates (the latest cumulative update) fixes it. If updating isn't possible, turning the protection off for Filee alone usually works: in PowerShell as administrator, run Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, then the same for filee-cli.exe and for the installer's file name (or use the portable ZIP). To undo it, remove those entries in Windows Security → App & browser control → Exploit protection settings → Program settings.`,
    `Hal ini terjadi pada Windows 10 yang sudah lama tidak diperbarui, di PC yang prosesornya mendukung Hardware-enforced Stack Protection (CET). Windows mengaktifkan proteksi tersebut tetapi kekurangan komponen yang dibutuhkan .NET, sehingga Filee dan installer-nya langsung berhenti, tanpa jendela atau pesan. Memasang pembaruan Windows yang tersedia (pembaruan kumulatif terbaru) akan menyelesaikannya. Jika pembaruan tidak memungkinkan, menonaktifkan proteksi khusus untuk Filee biasanya berhasil: di PowerShell sebagai administrator, jalankan Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, lalu lakukan hal yang sama untuk filee-cli.exe dan untuk nama file installer (atau gunakan ZIP portabel). Untuk membatalkannya, hapus entri tersebut di Windows Security → App & browser control → Exploit protection settings → Program settings.`],
  [`Can I convert many files at once?`, `Bisakah saya mengonversi banyak file sekaligus?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Bisa. Pilih file sebanyak yang Anda mau dan lepaskan sekali saja: Filee mengonversinya secara paralel, satu file yang gagal tidak pernah menghentikan yang lain, dan preset dapat menggabungkan semuanya menjadi satu PDF atau mengemasnya menjadi satu ZIP.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `Bisakah saya mengonversi dari menu klik kanan Windows 11?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Bisa. Klik kanan file di File Explorer lalu pilih "Konversi dengan Filee". Di Windows 11 Anda juga dapat menempatkannya di menu tingkat atas, tanpa "Tampilkan opsi lainnya": klik "Tambahkan ke menu utama" sekali di Pengaturan → Umum dan setujui permintaan administrator. Kirim ke, pintasan keyboard, dan area drop zone di jendela utama juga bisa digunakan.`],
  [`Can Filee convert from the command line or automatically?`,
    `Bisakah Filee mengonversi dari baris perintah atau secara otomatis?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Bisa. Setup dapat menambahkan perintah filee ke PATH: filee convert *.heic --to jpg mengonversi file, wildcard, dan folder dengan preset Anda, mencetak JSON untuk skrip, dan mengembalikan exit code. Folder pantau otomatis mengonversi file yang masuk ke sebuah folder dan dapat memindahkan file aslinya ke tempat lain. Atur di halaman Folder pantau di aplikasi atau dengan filee watch di terminal.`],
  [`How do I convert a file, for example HEIC to JPG?`, `Bagaimana cara mengonversi file, misalnya HEIC ke JPG?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Pilih file di File Explorer, tahan Ctrl (atau tombol yang Anda pilih), lalu seret. Menu donut berisi format terbuka di kursor: lepaskan file di JPG dan file baru muncul di samping file aslinya. Tersedia panduan langkah demi langkah untuk konversi yang paling umum.`],
  [`Why use Filee instead of an online converter?`, `Mengapa menggunakan Filee alih-alih konverter online?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Konverter online mengunggah file Anda ke server milik orang lain, sering membatasi ukuran dan jumlah file, dan bergantung pada koneksi yang cepat. Filee mengonversi di PC Anda: file pribadi tetap pribadi, video besar dan ratusan file bukan masalah, dan semuanya bekerja tanpa internet, gratis, dan tanpa iklan.`],
  [`Which operating systems are supported?`, `Sistem operasi apa saja yang didukung?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Windows 10 dan 11 (64-bit) serta Linux (x64 dan ARM64, Ubuntu 22.04 atau lebih baru) adalah rilis penuh. Di Linux, gestur seret memerlukan sesi X11; di KDE Plasma dengan Wayland fitur ini masih eksperimental, dan di desktop Wayland lainnya area drop zone serta menu klik kanan pengelola file tetap berfungsi. macOS 13 atau lebih baru (Apple silicon dan Intel) masih berupa preview: aplikasi ini belum dinotarisasi, sehingga macOS meminta Anda mengizinkannya sekali di Privacy & Security. Pilih sistem Anda di bagian unduhan.`],
]);
